import json

import yaml

from prompty.model import TurnEngineResult


def test_load_json_turnengineresult():
    json_data = r'''
    {
      "commit": {
        "sessionId": "sess_abc123",
        "turnId": "turn_abc123",
        "status": "success",
        "messages": [],
        "iterations": 1,
        "lastSequence": 1,
        "contextState": {}
      }
    }
    '''
    data = json.loads(json_data, strict=False)
    instance = TurnEngineResult.load(data)
    assert instance is not None

